"""Customer history widget and one shared floating staff inbox."""


def render_support_widget():
    return r'''<style>
.tr-chat-launcher{position:fixed;right:22px;bottom:22px;z-index:80;border:1px solid #b2dfcd66;border-radius:100px;background:#a8d8c4;color:#142920;padding:13px 19px;font:700 13px 'Segoe UI',Arial,sans-serif;box-shadow:0 8px 30px #0004;cursor:pointer}.tr-chat-box{position:fixed;right:22px;bottom:82px;width:360px;max-width:calc(100vw - 28px);height:480px;max-height:calc(100dvh - 110px);z-index:81;display:flex;flex-direction:column;background:#1c3038;border:1px solid #b2dfcd44;border-radius:20px;box-shadow:0 16px 70px #0008;overflow:hidden}.tr-chat-box[hidden],.tr-chat-compose[hidden],.tr-chat-signin[hidden]{display:none}.tr-chat-header{padding:16px 18px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid #ffffff18}.tr-chat-header h2{font-size:16px;margin:0}.tr-chat-header button{background:none;border:0;color:#dcebe5;font-size:22px;cursor:pointer}.tr-chat-messages{padding:16px;overflow-y:auto;flex:1;min-height:0;display:flex;flex-direction:column;gap:10px}.tr-chat-bubble{background:#ffffff08;border-radius:12px;padding:10px 12px;font:13px/1.5 'Segoe UI',Arial,sans-serif;color:#dcebe5;white-space:pre-wrap;overflow-wrap:anywhere}.tr-chat-bubble.customer{background:#40645a80;margin-left:24px}.tr-chat-bubble.staff{margin-right:20px}.tr-chat-bubble small{display:block;font-size:10px;color:#a7c5bd;margin-bottom:4px}.tr-chat-compose{border-top:1px solid #ffffff18;padding:12px;display:flex;gap:8px}.tr-chat-compose textarea{width:100%;min-width:0;height:60px;padding:10px;resize:none;font-size:13px}.tr-chat-compose button{padding:8px 12px;font-size:12px}.tr-chat-notice{margin:0;padding:0 12px 10px;color:#bcd0ce;font-size:11px;line-height:1.4}.tr-chat-signin{padding:12px 16px;font-size:13px;line-height:1.5;border-top:1px solid #ffffff18}.tr-chat-signin a{color:#b9e4d1}@media(max-width:480px){.tr-chat-launcher{right:14px;bottom:14px}.tr-chat-box{right:14px;bottom:72px}}
.tr-chat-history{padding:8px 12px;border-bottom:1px solid #ffffff18;display:flex;gap:6px;align-items:center}.tr-chat-history select{min-width:0;flex:1;padding:7px;font-size:11px}.tr-chat-history button{font-size:11px;padding:7px}.tr-chat-history[hidden]{display:none}.tr-chat-older{font-size:11px;align-self:center}.tr-chat-customer-area{display:contents}.tr-chat-staff-area{display:flex;flex:1;min-height:0}.tr-chat-staff-area[hidden],.tr-chat-customer-area[hidden]{display:none}.tr-chat-box.tr-chat-staff{width:940px;height:650px}.tr-chat-staff-area iframe{width:100%;height:100%;border:0;min-height:0;background:#17292f}.tr-support-count{display:inline-flex;justify-content:center;align-items:center;min-width:21px;height:21px;padding:0 5px;box-sizing:border-box;border-radius:100px;background:#d84858;color:white;font-size:11px;font-weight:700;line-height:1;margin-left:6px}.tr-support-count[hidden],.tr-chat-older[hidden]{display:none!important}</style><button class="tr-chat-launcher" id="tr-chat-open" type="button" aria-expanded="false" aria-controls="tr-chat-box">Live Chat<span class="tr-support-count" data-support-count hidden></span></button><section class="tr-chat-box" id="tr-chat-box" aria-label="TableRadar live chat" hidden><header class="tr-chat-header"><h2 id="tr-chat-title">TableRadar support</h2><button type="button" id="tr-chat-close" aria-label="Close live chat">×</button></header><div class="tr-chat-staff-area" id="tr-chat-staff-area" hidden></div><div class="tr-chat-customer-area" id="tr-chat-customer-area"><div class="tr-chat-history" id="tr-chat-history" hidden><select id="tr-chat-cases" aria-label="Conversation history"></select><button class="tr-button" type="button" id="tr-chat-new">New request</button></div><div class="tr-chat-messages" id="tr-chat-messages" role="log" aria-live="polite"><div class="tr-chat-bubble staff">Hi! Welcome to TableRadar. How can we help?</div></div><button class="tr-button tr-chat-older" type="button" id="tr-chat-older" hidden>Earlier messages</button><div class="tr-chat-signin" id="tr-chat-signin" hidden><a href="/signin_login">Sign in</a> or <a href="/signup">create an account</a> to message our team and keep your conversation.</div><form class="tr-chat-compose" id="tr-chat-compose" hidden><textarea name="message" maxlength="2000" aria-label="Your message" placeholder="Write a message…" required></textarea><button class="tr-button" type="submit">Send</button></form><p class="tr-chat-notice" id="tr-chat-notice">Our administrators and managers will reply here. Please do not send passwords or payment keys.</p></div></section><script>(function(){
const box=document.getElementById('tr-chat-box'),launch=document.getElementById('tr-chat-open'),messages=document.getElementById('tr-chat-messages'),form=document.getElementById('tr-chat-compose'),signin=document.getElementById('tr-chat-signin'),notice=document.getElementById('tr-chat-notice'),history=document.getElementById('tr-chat-history'),cases=document.getElementById('tr-chat-cases'),newButton=document.getElementById('tr-chat-new'),older=document.getElementById('tr-chat-older'),staffArea=document.getElementById('tr-chat-staff-area'),customerArea=document.getElementById('tr-chat-customer-area');let csrf='',nonce='',pendingBody='',busy=false,staff=false,selected='',active='',newRequest=false,items=new Map(),caseSignature='',frame=null,loading=false,version=0;
function count(value){const n=Math.max(0,Number(value)||0);document.querySelectorAll('[data-support-count]').forEach(b=>{b.textContent=String(n);b.hidden=n===0;b.setAttribute('aria-label',n+' conversations need a reply')})}window.addEventListener('tr-support-count',e=>count(e.detail));
function draw(list,prepend){if(!prepend&&list.every(m=>items.has(m.id)))return;const oldTop=messages.scrollTop,oldHeight=messages.scrollHeight,bottom=oldHeight-oldTop-messages.clientHeight<60;list.forEach(m=>items.set(m.id,m));messages.replaceChildren();const welcome=document.createElement('div');welcome.className='tr-chat-bubble staff';welcome.textContent='Hi! Welcome to TableRadar. How can we help?';messages.append(welcome);Array.from(items.values()).sort((a,b)=>a.id-b.id).forEach(m=>{const b=document.createElement('div');b.className='tr-chat-bubble '+(m.sender==='customer'?'customer':'staff');const label=document.createElement('small');label.textContent=m.sender==='customer'?'You':'TableRadar team';b.append(label,document.createTextNode(m.body));messages.append(b)});if(prepend)messages.scrollTop=messages.scrollHeight-oldHeight;else if(bottom)messages.scrollTop=messages.scrollHeight;else messages.scrollTop=oldTop}
function showStaff(){box.classList.add('tr-chat-staff');customerArea.hidden=true;staffArea.hidden=false;document.getElementById('tr-chat-title').textContent='Customer conversations';if(!box.hidden&&!frame){frame=document.createElement('iframe');frame.title='TableRadar customer conversations';frame.src='/staff/chat?compact=1';staffArea.append(frame)}if(frame&&!box.hidden)frame.contentWindow.postMessage({type:'tr-chat-resume'},location.origin)}
async function load(before){if(loading)return;loading=true;const ticket=version;try{const query=new URLSearchParams();if(selected)query.set('case_id',selected);if(before)query.set('before',String(before));const r=await fetch('/support/chat?'+query,{credentials:'same-origin',cache:'no-store'}),data=await r.json();if(!r.ok)throw Error(data.error||'Chat could not be loaded.');if(ticket!==version)return;csrf=data.csrf||'';staff=Boolean(data.staff);if(staff){count(data.waiting_count);showStaff();return}count(0);box.classList.remove('tr-chat-staff');customerArea.hidden=false;staffArea.hidden=true;document.getElementById('tr-chat-title').textContent='TableRadar support';signin.hidden=data.signed_in;active=data.active_case_id||'';const conversation=data.conversation||null;if(newRequest&&!active){form.hidden=!data.signed_in;older.hidden=true;history.hidden=!data.signed_in;return}newRequest=false;const next=conversation?conversation.id:'';if(next!==selected){selected=next;items=new Map()}const signature=JSON.stringify(data.cases||[]);if(signature!==caseSignature){caseSignature=signature;cases.replaceChildren();(data.cases||[]).forEach(c=>{const option=document.createElement('option');option.value=c.id;option.textContent=(c.state==='open'?'Active request':c.state==='finished'?'Finished request':'Archived request')+' · '+new Date(c.created_at).toLocaleDateString();cases.append(option)})}cases.value=selected;history.hidden=!data.signed_in||!(data.cases||[]).length;form.hidden=!data.signed_in||Boolean(conversation&&conversation.state!=='open');newButton.textContent=active?'Active request':'New request';newButton.disabled=Boolean(active&&active===selected);draw(conversation?conversation.messages:[],Boolean(before));if(before||!items.size||Math.min(...items.keys())>=Math.min(...((conversation&&conversation.messages)||[]).map(m=>m.id)))older.hidden=!(conversation&&conversation.has_older);if(conversation&&conversation.state!=='open')notice.textContent='This conversation is finished. Its history is saved. Choose New request to contact us again.'}catch(e){notice.textContent=e.message||'Chat is temporarily unavailable. Please try again shortly.'}finally{loading=false}}
function open(){box.hidden=false;launch.setAttribute('aria-expanded','true');load();if(staff)showStaff()}function close(){box.hidden=true;launch.setAttribute('aria-expanded','false');if(frame)frame.contentWindow.postMessage({type:'tr-chat-pause'},location.origin);launch.focus()}
launch.addEventListener('click',()=>box.hidden?open():close());document.getElementById('tr-chat-close').addEventListener('click',close);document.querySelectorAll('[data-open-live-chat]').forEach(b=>b.addEventListener('click',open));
cases.addEventListener('change',()=>{version++;selected=cases.value;newRequest=false;items=new Map();messages.replaceChildren();notice.textContent='';load()});newButton.addEventListener('click',()=>{version++;if(active){selected=active;newRequest=false;load();return}selected='';newRequest=true;items=new Map();messages.replaceChildren();notice.textContent='Write a message to start a new request. Previous conversations stay in History.';form.hidden=false;older.hidden=true;form.querySelector('textarea').focus()});older.addEventListener('click',()=>{if(items.size)load(Math.min(...items.keys()))});
form.addEventListener('submit',async e=>{e.preventDefault();if(busy)return;const input=form.querySelector('textarea'),text=input.value.trim();if(!text)return;busy=true;form.querySelector('button').disabled=true;if(!nonce||pendingBody!==text){nonce=crypto.randomUUID();pendingBody=text}try{const data=new URLSearchParams({body:text,csrf,nonce,case_id:selected});const r=await fetch('/support/chat/message',{method:'POST',credentials:'same-origin',body:data}),result=await r.json();if(!r.ok)throw Error(result.error||'Message could not be sent. Please try again.');if(input.value.trim()===text)input.value='';nonce='';pendingBody='';selected=result.case_id||selected;newRequest=false;notice.textContent='Message sent. Our team will reply here.';await load()}catch(e){notice.textContent=e.message||'Message could not be sent.'}finally{busy=false;form.querySelector('button').disabled=false}});
async function refreshCount(){if(!staff)return;try{const r=await fetch('/staff/chat/count',{cache:'no-store',credentials:'same-origin'});if(r.ok)count((await r.json()).waiting_count);else count(0)}catch(e){}}load();setInterval(()=>{if(document.visibilityState==='hidden')return;if(staff)refreshCount();else if(!box.hidden)load()},7000);
})();</script>'''
